                dispatchTomatoTaskAttrUpdated(attrContext, TASK_REPEAT_STATE_ATTR, attrs[TASK_REPEAT_STATE_ATTR]);
                try { postJSON('/api/sqlite/flushTransaction', {}).catch(() => {}); } catch (e) {}
